function createSortingVisualizer(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const barWidth = width / 50;
    let bars = Array.from({ length: 50 }, () => Math.floor(Math.random() * (height - 20)) + 20);
    let algorithm = 'bubble';
    let speed = 1000;
    let stepByStep = true;
    let complexity = '';
    let callStackDepth = 0;
    let comparisonCount = 0;
    let swapCount = 0;

    function drawBars() {
        ctx.clearRect(0, 0, width, height);
        for (let i = 0; i < bars.length; i++) {
            ctx.fillStyle = 'blue';
            if (i === pivotIndex) {
                ctx.fillStyle = 'blue';
            }
            if (bars[i] === sortedValue) {
                ctx.fillStyle = 'green';
            }
            if (comparingIndices.includes(i)) {
                ctx.fillStyle = 'red';
            }
            if (swappingIndices.includes(i)) {
                ctx.fillStyle = 'yellow';
            }
            ctx.fillRect(i * barWidth, height - bars[i], barWidth, bars[i]);
        }
    }

    function scrambleBars(pattern) {
        switch (pattern) {
            case 'random':
                bars = Array.from({ length: 50 }, () => Math.floor(Math.random() * (height - 20)) + 20);
                break;
            case 'reverse':
                bars.sort((a, b) => b - a);
                break;
            case 'nearlySorted':
                bars.sort((a, b) => a - b);
                for (let i = 0; i < 5; i++) {
                    const index1 = Math.floor(Math.random() * 45);
                    const index2 = Math.floor(Math.random() * 45);
                    [bars[index1], bars[index2]] = [bars[index2], bars[index1]];
                }
                break;
        }
    }

    function bubbleSort() {
        comparing (true) {
            let swapped = false;
            for (let i = 0; i < bars.length - 1; i++) {
                comparingIndices = [i, i + 1];
                if (bars[i] > bars[i + 1]) {
                    swapCount++;
                    [bars[i], bars[i + 1]] = [bars[i + 1], bars[i]];
                    swapped = true;
                }
                drawBars();
                if (!stepByStep) return;
            }
            if (!swapped) return;
        }
    }

    function quickSort(arr, low, high) {
        if (low < high) {
            callStackDepth++;
            const pi = partition(arr, low, high);
            quickSort(arr, low, pi - 1);
            quickSort(arr, pi + 1, high);
            callStackDepth--;
        }
    }

    function partition(arr, low, high) {
        pivotIndex = high;
        pivot = arr[high];
        let i = (low - 1);

        for (let j = low; j <= high - 1; j++) {
            comparingIndices = [j, high];
            if (arr[j] < pivot) {
                i++;
                [arr[i], arr[j]] = [arr[j], arr[i]];
                swapCount++;
            }
            drawBars();
            if (!stepByStep) return high;
        }
        [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
        swapCount++;
        return (i + 1);
    }

    function mergeSort(arr) {
        if (arr.length > 1) {
            callStackDepth++;
            const mid = Math.floor(arr.length / 2);
            const left = arr.slice(0, mid);
            const right = arr.slice(mid);

            mergeSort(left);
            mergeSort(right);

            let i = 0, j = 0, k = 0;

            while (i < left.length && j < right.length) {
                comparingIndices = [i + k, j + k];
                if (left[i] < right[j]) {
                    arr[k++] = left[i++];
                } else {
                    arr[k++] = right[j++];
                }
                swapCount++;
                drawBars();
                if (!stepByStep) return;
            }

            while (i < left.length) {
                arr[k++] = left[i++];
                swapCount++;
                drawBars();
                if (!stepByStep) return;
            }

            while (j < right.length) {
                arr[k++] = right[j++];
                swapCount++;
                drawBars();
                if (!stepByStep) return;
            }
            callStackDepth--;
        }
    }

    function heapify(arr, n, i) {
        let largest = i;
        const l = 2 * i + 1;
        const r = 2 * i + 2;

        comparingIndices = [i, l];
        if (l < n && arr[l] > arr[largest]) {
            largest = l;
        }

        comparingIndices = [largest, r];
        if (r < n && arr[r] > arr[largest]) {
            largest = r;
        }

        if (largest !== i) {
            [arr[i], arr[largest]] = [arr[largest], arr[i]];
            swapCount++;
            heapify(arr, n, largest);
        }
    }

    function heapSort(arr) {
        const n = arr.length;

        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }

        for (let i = n - 1; i > 0; i--) {
            [arr[0], arr[i]] = [arr[i], arr[0]];
            swapCount++;
            heapify(arr, i, 0);
        }
    }

    function radixSort(arr) {
        const maxVal = Math.max(...arr);
        let exp = 1;
        while (maxVal / exp > 0) {
            countinging(arr, exp);
            exp *= 10;
        }
    }

    function countingSort(arr, exp) {
        const output = new Array(arr.length);
        const count = new Array(10).fill(0);

        for (let i = 0; i < arr.length; i++) {
            const index = Math.floor(arr[i] / exp) % 10;
            count[index]++;
        }

        for (let i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        for (let i = arr.length - 1; i >= 0; i--) {
            const index = Math.floor(arr[i] / exp) % 10;
            output[count[index] - 1] = arr[i];
            count[index]--;
        }

        for (let i = 0; i < arr.length; i++) {
            arr[i] = output[i];
        }
    }

    function runAlgorithm() {
        switch (algorithm) {
            case 'bubble':
                bubbleSort();
                break;
            case 'quick':
                quickSort(bars, 0, bars.length - 1);
                break;
            case 'merge':
                mergeSort(bars);
                break;
            case 'heap':
                heapSort(bars);
                break;
            case 'radix':
                radixSort(bars);
                break;
        }
        complexity = `O(${getComplexity(algorithm)})`;
    }

    function getComplexity(name) {
        switch (name) {
            case 'bubble':
                return 'n^2';
            case 'quick':
                return 'n log n';
            case 'merge':
                return 'n log n';
            case 'heap':
                return 'n log n';
            case 'radix':
                return 'nk';
            default:
                return 'N/A';
        }
    }

    function updateUI() {
        // Update UI elements like dropdown, slider, etc.
    }

    function visualize() {
        drawBars();
        requestAnimationFrame(visualize);
    }

    visualize();
}
